int sctp_get_assoc_stats(struct sock *sk, int len, char __user *optval, int __user *optlen)
{
    struct sctp_association *asoc;
    struct sctp_stats stats;
    int ret = 0;

    if (!sk || !optval || !optlen)
        return -EINVAL;

    if (len < sizeof(stats))
        return -EINVAL;

    asoc = sctp_id2assoc(sk, 0);
    if (!asoc)
        return -ENOENT;

    memset(&stats, 0, sizeof(stats));

    stats.assoc_id = asoc->assoc_id;
    stats.cwnd = asoc->cwnd;
    stats.ssthresh = asoc->ssthresh;
    stats.rtx_cnt = asoc->stats.rtx_cnt;
    stats.ootb_cnt = asoc->stats.ootb_cnt;
    stats.pmtu = asoc->pmtu;

    stats.max_rto = asoc->rto;
    if (asoc->stats.rto_max < asoc->rto)
        stats.max_rto = asoc->rto;

    if (copy_to_user(optval, &stats, sizeof(stats)))
        ret = -EFAULT;

    if (put_user(sizeof(stats), optlen))
        ret = -EFAULT;

    return ret;
}

