int sctp_get_association_stats(struct sock *sk, int len, char __user *optval, int __user *optlen)
{
    struct sctp_association *asoc = sctp_id2assoc(sk);
    struct sctp_stats stats;
    int ret = 0;

    if (!asoc)
        return -EINVAL;

    if (len < sizeof(stats))
        return -EINVAL;

    memset(&stats, 0, sizeof(stats));
    stats.assoc_id = asoc->assoc_id;
    stats.cumu_flight = asoc->c.s.sack->cumulative_tsn;
    stats.rwnd = asoc->a_rwnd;
    stats.osb = asoc->sent_queue->cnt;
    stats.isb = asoc->recv_queue->cnt;
    stats.established = jiffies_to_msecs(jiffies - asoc->time_last_data_sent);

    if (asoc->rto > stats.max_rto)
        stats.max_rto = asoc->rto;

    if (copy_to_user(optval, &stats, sizeof(stats)))
        return -EFAULT;

    if (put_user(sizeof(stats), optlen))
        return -EFAULT;

    return 0;
}
